"use client";

import {
  CreditCardIcon,
  Folder01Icon,
  Home01Icon,
  Plug01Icon,
  Settings02Icon,
  SquareLock02Icon,
  UserGroupIcon,
} from "@hugeicons/core-free-icons";
import type * as React from "react";
import { useMemo, useState } from "react";

import { cn } from "@/lib/utils";

import { BillingActionsProvider, DEMO_ACTIONS } from "./actions";
import type { BillingActions, BillingInfo } from "./actions";
import { AppShell } from "./app-shell";
import type { AppShellProps } from "./app-shell";
import { BillingDetailsCard, DEMO_BILLING } from "./billing-details";
import { CardMark } from "./brand-marks";
import { describe, healthOf, statusLine } from "./card-data";
import type { CardBook, SavedCard } from "./card-data";
import { PaymentMethodsDialog } from "./payment-methods-dialog";
import { LIFT } from "./surface";
import {
  Amount,
  LinkAction,
  Pill,
  RowDownload,
  SummaryCard,
  usd,
  useAppear,
} from "./ui";
import type { WalletState } from "./wallets";

/* ─────────────────────────────────────────────────────────
 * BILLING SETTINGS: a SaaS subscription billing page inside the app.
 *
 *   ┌ Current plan ─────────────── Active ┐ ┌ Payment method ─ Expiring ┐
 *   │ $25 per month                       │ │ [VISA] Visa ending 4242    │
 *   │ Plan   Seats   Renews   Next invoice│ │ Expires soon, 01/27        │
 *   │ Change plan ›                       │ │ Manage payment methods ›   │
 *   └─────────────────────────────────────┘ └────────────────────────────┘
 *   ┌ Billing details ──────────────────────────────────────────── Edit ┐
 *   ┌ Invoices ─────────────────────────────────────────────── View all ┐
 *   │ Invoice   Date   Plan   Status   Amount                         ↓ │
 *
 * One fact per place: the price lives on the plan card, every payment in
 * the table. Details are label over value, never joined with dots.
 *
 * "Manage payment methods" opens the dialog: a method switcher (Cards,
 * PayPal, Apple Pay, Google Pay) over one panel; cards are slots you
 * choose, edit, add and remove in place. Every call to your server goes
 * through `actions` (see actions.tsx); leave it out for the demo.
 * ───────────────────────────────────────────────────────── */

export interface BillingPlan {
  /** Plan name, e.g. "Pro". */
  name: string;
  /** Price per interval, in dollars. */
  price: number;
  /** Billed each month or each year. */
  interval: "month" | "year";
  /** Seats on the plan. */
  seats: number;
  /** When it renews, as you want it shown, e.g. "Dec 1, 2026". */
  renewsOn: string;
  /** The next invoice's total, in dollars. */
  nextInvoice: number;
  /** "active" shows a green pill; "past_due" an amber one. */
  status: "active" | "past_due" | "canceled";
}

export interface Invoice {
  /** Shown as the invoice number, e.g. "#1042". */
  id: string;
  /** As you want it shown, e.g. "Nov 1, 2026". */
  date: string;
  /** What it was for, e.g. "Pro, 10 seats". */
  description: string;
  /** In dollars. */
  amount: number;
  /** Shown as a pill: Paid, Open, Failed or Refunded. */
  status: "paid" | "open" | "failed" | "refunded";
}

export interface BillingSettingsProps {
  /** The app around the page: brand, sidebar links, the person. */
  shell?: Partial<Omit<AppShellProps, "children">>;
  /** The current plan and its next invoice. */
  plan?: BillingPlan;
  /** Saved cards, the default one and the backup. */
  cards?: CardBook;
  /** Wallets already connected (the account), or null. */
  wallets?: WalletState;
  /** What prints on every invoice. */
  billing?: BillingInfo;
  /** Recent invoices, newest first. */
  invoices?: Invoice[];
  /** Your server calls; anything left out uses the demo. */
  actions?: Partial<BillingActions>;
  /** Opens your plan picker. */
  onChangePlan?: () => void;
  /** Opens your full invoice list. */
  onViewAllInvoices?: () => void;
  /** Height and placement of the app, e.g. "h-dvh" or "h-[46rem]". */
  className?: string;
}

/* ---------------------------------- Demo ---------------------------------- */

export const DEMO_PLAN: BillingPlan = {
  interval: "month",
  name: "Pro",
  nextInvoice: 25,
  price: 25,
  renewsOn: "Dec 1, 2026",
  seats: 10,
  status: "active",
};

// One of each health, so every state shows: expiring soon, declined
// (Retry), expired (Update, can't be chosen).
export const DEMO_CARDS: CardBook = {
  backupId: "mc",
  cards: [
    {
      addedBy: "Maya Chen",
      addedOn: "Mar 2, 2024",
      brand: "visa",
      expires: "01/27",
      id: "visa",
      last4: "4242",
      name: "Maya Chen",
      nickname: "Company card",
    },
    {
      addedBy: "Sam Ortiz",
      addedOn: "Jun 18, 2025",
      brand: "mastercard",
      declinedOn: "Nov 1",
      expires: "08/28",
      id: "mc",
      last4: "8210",
      name: "Sam Ortiz",
    },
    {
      addedBy: "Maya Chen",
      addedOn: "Oct 9, 2022",
      brand: "amex",
      expires: "10/26",
      id: "amex",
      last4: "1005",
      name: "Maya Chen",
      nickname: "Personal",
    },
  ],
  defaultId: "visa",
};

export const DEMO_WALLETS: WalletState = {
  apple: null,
  google: null,
  paypal: "maya@acme.co",
};

export const DEMO_INVOICES: Invoice[] = [
  {
    amount: 25,
    date: "Nov 1, 2026",
    description: "Pro, 10 seats",
    id: "#1042",
    status: "paid",
  },
  {
    amount: 25,
    date: "Oct 1, 2026",
    description: "Pro, 10 seats",
    id: "#1031",
    status: "paid",
  },
  {
    amount: 18.4,
    date: "Sep 14, 2026",
    description: "Pro, prorated",
    id: "#1019",
    status: "paid",
  },
  {
    amount: 12,
    date: "Sep 1, 2026",
    description: "Starter, 4 seats",
    id: "#1007",
    status: "paid",
  },
];

export const DEMO_SHELL: Omit<AppShellProps, "children"> = {
  active: "billing",
  brand: "Acme",
  brandColor: "#4F46E5",
  description: "Your plan, invoices and the card we charge.",
  groups: [
    {
      items: [
        { icon: Home01Icon, id: "home", label: "Home" },
        { icon: Folder01Icon, id: "projects", label: "Projects" },
        { icon: UserGroupIcon, id: "members", label: "Members" },
        { icon: Plug01Icon, id: "integrations", label: "Integrations" },
      ],
    },
    {
      items: [
        { icon: Settings02Icon, id: "general", label: "General" },
        { icon: CreditCardIcon, id: "billing", label: "Billing" },
        { icon: SquareLock02Icon, id: "security", label: "Security" },
      ],
      label: "Settings",
    },
  ],
  title: "Billing",
  trail: ["Settings", "Billing"],
  user: { email: "maya@acme.co", name: "Maya Chen" },
};

/* --------------------------------- Pieces --------------------------------- */

const HEALTH_TONE = {
  declined: "text-red-600 dark:text-red-400",
  expired: "text-red-600 dark:text-red-400",
  expiring: "text-amber-700 dark:text-amber-400",
  ok: "text-muted-foreground",
  updated: "text-emerald-700 dark:text-emerald-400",
};

const HealthPill = ({ card }: { card: SavedCard }) => {
  const health = healthOf(card);
  if (health === "expiring") {
    return <Pill tone="warn">Expiring</Pill>;
  }
  if (health === "declined") {
    return <Pill tone="bad">Payment failed</Pill>;
  }
  return null;
};

const PLAN_STATUS = {
  active: { tone: "ok", word: "Active" },
  canceled: { tone: "muted", word: "Canceled" },
  past_due: { tone: "warn", word: "Past due" },
} as const;

const INVOICE_STATUS = {
  failed: { tone: "bad", word: "Failed" },
  open: { tone: "warn", word: "Open" },
  paid: { tone: "ok", word: "Paid" },
  refunded: { tone: "muted", word: "Refunded" },
} as const;

const Detail = ({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) => (
  <div className="flex flex-col gap-0.5">
    <dt className="text-muted-foreground text-xs">{label}</dt>
    <dd className="text-sm tabular-nums">{children}</dd>
  </div>
);

const TH =
  "text-muted-foreground bg-muted/60 dark:bg-muted/40 h-8 px-2 text-left text-xs font-normal first:rounded-l-lg last:rounded-r-lg sm:px-3";
const TD = "h-12 px-2 text-sm sm:px-3";

const InvoiceTable = ({
  invoices,
  onViewAll,
}: {
  invoices: Invoice[];
  onViewAll?: () => void;
}) => (
  <section
    aria-labelledby="billing-invoices"
    className={cn(LIFT, "bg-card flex flex-col gap-2 rounded-2xl p-2")}
  >
    <div className="flex items-center justify-between gap-3 px-2 pt-2">
      <h2 id="billing-invoices" className="text-sm font-medium">
        Invoices
      </h2>
      <LinkAction label="View all invoices" onClick={onViewAll}>
        View all
      </LinkAction>
    </div>
    {/* relative: keeps the hidden "Download" header label inside. */}
    <div className="relative overflow-x-auto">
      <table className="w-full border-separate border-spacing-0 sm:min-w-[30rem]">
        <thead>
          <tr>
            <th scope="col" className={TH}>
              Invoice
            </th>
            <th scope="col" className={cn(TH, "max-sm:hidden")}>
              Date
            </th>
            <th scope="col" className={cn(TH, "max-sm:hidden")}>
              Plan
            </th>
            <th scope="col" className={TH}>
              Status
            </th>
            <th scope="col" className={cn(TH, "text-right")}>
              Amount
            </th>
            <th scope="col" className={cn(TH, "w-12")}>
              <span className="sr-only">Download</span>
            </th>
          </tr>
        </thead>
        <tbody>
          {invoices.map((row) => (
            <tr key={row.id}>
              <td className={cn(TD, "tabular-nums")}>
                {row.id}
                {/* Phones: the date folds under the number. */}
                <span className="text-muted-foreground block text-xs sm:hidden">
                  {row.date}
                </span>
              </td>
              <td
                className={cn(
                  TD,
                  "text-muted-foreground tabular-nums max-sm:hidden"
                )}
              >
                {row.date}
              </td>
              <td className={cn(TD, "text-muted-foreground max-sm:hidden")}>
                {row.description}
              </td>
              <td className={TD}>
                <span className="inline-flex">
                  <Pill tone={INVOICE_STATUS[row.status].tone}>
                    {INVOICE_STATUS[row.status].word}
                  </Pill>
                </span>
              </td>
              <td className={cn(TD, "text-right tabular-nums")}>
                {usd(row.amount)}
              </td>
              <td className={cn(TD, "px-1 text-right")}>
                <RowDownload id={row.id} what={`invoice ${row.id}`} />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  </section>
);

/* ---------------------------------- Block --------------------------------- */

export const BillingSettings = ({
  shell,
  plan = DEMO_PLAN,
  cards = DEMO_CARDS,
  wallets = DEMO_WALLETS,
  billing = DEMO_BILLING,
  invoices = DEMO_INVOICES,
  actions,
  onChangePlan,
  onViewAllInvoices,
  className,
}: BillingSettingsProps) => {
  const { ref, shown } = useAppear({ price: plan.price }, { price: 0 });
  const [book, setBook] = useState(cards);
  const [managing, setManaging] = useState(false);
  const merged = useMemo(() => ({ ...DEMO_ACTIONS, ...actions }), [actions]);
  const card = book.cards.find((each) => each.id === book.defaultId);
  const backup = book.cards.find((each) => each.id === book.backupId);
  const status = PLAN_STATUS[plan.status];

  return (
    <BillingActionsProvider value={merged}>
      <AppShell {...DEMO_SHELL} {...shell} className={className}>
        <div className="flex w-full flex-col gap-3">
          <div ref={ref} className="grid w-full gap-3 lg:grid-cols-3">
            <SummaryCard
              label="Current plan"
              className="lg:col-span-2"
              aside={<Pill tone={status.tone}>{status.word}</Pill>}
            >
              <Amount
                text={usd(shown.price, false)}
                suffix={plan.interval === "month" ? "per month" : "per year"}
              />
              <dl className="grid grid-cols-2 gap-x-6 gap-y-3 sm:grid-cols-4">
                <Detail label="Plan">{plan.name}</Detail>
                <Detail label="Seats">{plan.seats}</Detail>
                <Detail label="Renews">{plan.renewsOn}</Detail>
                <Detail label="Next invoice">{usd(plan.nextInvoice)}</Detail>
              </dl>
              <div className="mt-auto">
                <LinkAction onClick={onChangePlan}>Change plan</LinkAction>
              </div>
            </SummaryCard>

            <SummaryCard
              label="Payment method"
              aside={card ? <HealthPill card={card} /> : null}
            >
              {card ? (
                <div className="flex items-center gap-3">
                  <CardMark brand={card.brand} />
                  <div className="flex min-w-0 flex-col gap-0.5">
                    <p className="truncate text-sm">{describe(card)}</p>
                    <p
                      className={cn(
                        "text-xs tabular-nums",
                        HEALTH_TONE[healthOf(card)]
                      )}
                    >
                      {statusLine(card)}
                    </p>
                  </div>
                </div>
              ) : (
                <p className="text-muted-foreground text-sm">No card on file</p>
              )}
              {backup ? (
                <p className="text-muted-foreground text-xs">
                  Backup: {describe(backup)}
                </p>
              ) : null}
              <div className="mt-auto">
                <LinkAction onClick={() => setManaging(true)}>
                  Manage payment methods
                </LinkAction>
              </div>
              <PaymentMethodsDialog
                open={managing}
                onOpenChange={setManaging}
                saved={book}
                onSave={setBook}
                initialWallets={wallets}
              />
            </SummaryCard>
          </div>

          <BillingDetailsCard initial={billing} />

          <InvoiceTable invoices={invoices} onViewAll={onViewAllInvoices} />
        </div>
      </AppShell>
    </BillingActionsProvider>
  );
};

export default BillingSettings;

"use client";

import {
  Menu01Icon,
  Notification03Icon,
  Search01Icon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import type { IconSvgElement } from "@hugeicons/react";
import type * as React from "react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

import { LIFT } from "./surface";

/* ─────────────────────────────────────────────────────────
 * APP SHELL: the app around the billing page: a sidebar (brand, nav, the person) and a top bar (where you
 * are, search, notifications), the page on a muted tint.
 *
 *   lg and up   sidebar beside the page
 *   below lg    the sidebar opens as a sheet from the menu button
 *
 * No rules: the sidebar and top bar sit on the background, the page on a
 * muted tint, and the change of colour is the edge. The active link
 * changes colour and background, never weight.
 * ───────────────────────────────────────────────────────── */

/** One link in the sidebar. */
export interface ShellLink {
  /** Unique id; matched against `active` to mark the current page. */
  id: string;
  /** Text in the sidebar, e.g. "Billing". */
  label: string;
  /** A Hugeicons icon from `@hugeicons/core-free-icons`. */
  icon: IconSvgElement;
}

/** A group of sidebar links, e.g. "Settings". */
export interface ShellGroup {
  /** Small heading above the group; leave out for none. */
  label?: string;
  /** The links in the group, in order. */
  items: ShellLink[];
}

export interface AppShellProps {
  /** Product name next to the monogram, e.g. "Acme". */
  brand: string;
  /** Background of the brand monogram, any CSS colour. */
  brandColor: string;
  /** The sidebar's link groups. */
  groups: ShellGroup[];
  /** Id of the current sidebar link. */
  active: string;
  /** Where the page sits, e.g. ["Settings", "Billing"]. */
  trail: string[];
  /** The page heading, e.g. "Billing". */
  title: string;
  /** One line under the heading. */
  description: string;
  /** Buttons at the right of the page header. */
  actions?: React.ReactNode;
  /** The signed-in person, shown at the foot of the sidebar. */
  user: { name: string; email: string };
  /** The page itself. */
  children: React.ReactNode;
  /** Height and placement, e.g. "h-dvh" (the default) or "h-[46rem]". */
  className?: string;
}

const initials = (name: string) =>
  name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

const Brand = ({ name, color }: { name: string; color: string }) => (
  <div className="flex items-center gap-2 px-2">
    <span
      aria-hidden
      style={{ backgroundColor: color }}
      className="flex size-6 items-center justify-center rounded-md text-xs font-medium text-white"
    >
      {name[0]}
    </span>
    <span className="text-sm font-medium">{name}</span>
  </div>
);

const Nav = ({
  groups,
  active,
  onPick,
}: {
  groups: ShellGroup[];
  active: string;
  onPick: (id: string) => void;
}) => (
  <nav aria-label="Main" className="flex flex-col gap-5">
    {groups.map((group) => (
      <div key={group.label ?? group.items[0]?.id} className="flex flex-col">
        {group.label ? (
          <p className="text-muted-foreground px-2 pb-1 text-xs">
            {group.label}
          </p>
        ) : null}
        <ul className="flex flex-col gap-0.5">
          {group.items.map((item) => {
            const current = item.id === active;
            return (
              <li key={item.id}>
                <a
                  href={`#${item.id}`}
                  aria-current={current ? "page" : undefined}
                  onClick={(event) => {
                    event.preventDefault();
                    onPick(item.id);
                  }}
                  className={cn(
                    "focus-visible:ring-ring/50 flex h-8 items-center gap-2 rounded-md px-2 text-sm outline-none focus-visible:ring-[3px]",
                    "transition-[background-color,color] duration-150 ease-out",
                    current
                      ? "bg-muted text-foreground"
                      : "text-muted-foreground hover:bg-muted/60 hover:text-foreground"
                  )}
                >
                  <HugeiconsIcon
                    icon={item.icon}
                    strokeWidth={1.75}
                    className="size-4 shrink-0"
                  />
                  {item.label}
                </a>
              </li>
            );
          })}
        </ul>
      </div>
    ))}
  </nav>
);

const Person = ({ user }: { user: AppShellProps["user"] }) => (
  <div className="flex items-center gap-2 px-2">
    <span
      aria-hidden
      className="bg-muted flex size-7 shrink-0 items-center justify-center rounded-full text-xs font-medium"
    >
      {initials(user.name)}
    </span>
    <div className="flex min-w-0 flex-col">
      <span className="truncate text-sm font-medium">{user.name}</span>
      <span className="text-muted-foreground truncate text-xs">
        {user.email}
      </span>
    </div>
  </div>
);

const SidebarBody = ({
  props,
  active,
  onPick,
}: {
  props: AppShellProps;
  active: string;
  onPick: (id: string) => void;
}) => (
  <div className="flex h-full flex-col gap-6 p-3">
    <Brand name={props.brand} color={props.brandColor} />
    <Nav groups={props.groups} active={active} onPick={onPick} />
    <div className="mt-auto">
      <Person user={props.user} />
    </div>
  </div>
);

export const AppShell = (props: AppShellProps) => {
  // Demo: other links highlight but the page stays on billing.
  const [active, setActive] = useState(props.active);
  const [open, setOpen] = useState(false);
  const pick = (id: string) => {
    setActive(id);
    setOpen(false);
  };

  return (
    <div
      className={cn(
        LIFT,
        "bg-background flex h-dvh w-full overflow-hidden rounded-2xl",
        props.className
      )}
    >
      <aside className="hidden w-56 shrink-0 lg:block">
        <SidebarBody props={props} active={active} onPick={pick} />
      </aside>

      <div className="flex min-w-0 flex-1 flex-col">
        <header className="flex h-12 shrink-0 items-center gap-2 px-3 lg:px-4">
          <Sheet open={open} onOpenChange={setOpen}>
            <SheetTrigger
              render={
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  aria-label="Open menu"
                  className="size-8 lg:hidden"
                />
              }
            >
              <HugeiconsIcon
                icon={Menu01Icon}
                strokeWidth={1.75}
                className="size-4"
              />
            </SheetTrigger>
            <SheetContent side="left" className="w-64 border-0 p-0">
              <SheetTitle className="sr-only">Menu</SheetTitle>
              <SheetDescription className="sr-only">
                Pages in {props.brand}
              </SheetDescription>
              <SidebarBody props={props} active={active} onPick={pick} />
            </SheetContent>
          </Sheet>
          <ol className="flex min-w-0 items-center gap-1.5 text-sm">
            {props.trail.map((step, index) => {
              const last = index === props.trail.length - 1;
              return (
                <li key={step} className="flex items-center gap-1.5">
                  {index > 0 ? (
                    <span aria-hidden className="text-muted-foreground/60">
                      /
                    </span>
                  ) : null}
                  <span
                    aria-current={last ? "page" : undefined}
                    className={cn(
                      "truncate",
                      last ? "font-medium" : "text-muted-foreground"
                    )}
                  >
                    {step}
                  </span>
                </li>
              );
            })}
          </ol>
          <div className="ml-auto flex items-center gap-1">
            <Button
              type="button"
              variant="ghost"
              size="icon"
              aria-label="Search"
              className="size-8"
            >
              <HugeiconsIcon
                icon={Search01Icon}
                strokeWidth={1.75}
                className="size-4"
              />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              aria-label="Notifications, 2 unread"
              className="relative size-8"
            >
              <HugeiconsIcon
                icon={Notification03Icon}
                strokeWidth={1.75}
                className="size-4"
              />
              <span
                aria-hidden
                className="bg-primary absolute top-1.5 right-1.5 size-1.5 rounded-full"
              />
            </Button>
          </div>
        </header>

        <main className="bg-muted/50 dark:bg-muted/20 min-h-0 flex-1 overflow-y-auto overscroll-contain rounded-tl-2xl max-lg:rounded-t-2xl">
          <div className="mx-auto flex w-full max-w-[64rem] flex-col gap-6 p-4 sm:p-6">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
              <div className="flex flex-col gap-1">
                <h1 className="text-lg font-medium">{props.title}</h1>
                <p className="text-muted-foreground text-sm text-pretty">
                  {props.description}
                </p>
              </div>
              {props.actions ? (
                <div className="flex shrink-0 gap-2">{props.actions}</div>
              ) : null}
            </div>
            {props.children}
          </div>
        </main>
      </div>
    </div>
  );
};

"use client";

import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import {
  Cancel01Icon,
  CreditCardIcon,
  SquareLock02Icon,
