  },
  disconnectWallet: async () => {
    await wait(300);
  },
  downloadInvoice: async () => {
    await wait(900);
  },
  retryCard: async () => {
    await wait(1100);
    // The bank had issued new details: the retry goes through on them.
    return { expires: "08/31", updatedByBank: true };
  },
  saveBilling: async () => {
    await wait(700);
  },
  saveCards: async () => {
    await wait(800);
  },
  verifyCard: async (card) => {
