"use client";

import { useState } from "react";

import type { CardBook, SavedCard } from "./card-data";
import type { CardEdit } from "./card-editor";

export type { CardBook } from "./card-data";

/* The dialog's draft: cards, the default, the backup. Nothing reaches
 * the page until Save; Cancel drops the whole draft. */

export interface Removed {
  card: SavedCard;
  index: number;
  wasBackup: boolean;
  /** Unique per removal, so a second removal restarts the toast. */
  key: number;
}

export const useCardDraft = (saved: CardBook) => {
  const [book, setBook] = useState(saved);
  const [removed, setRemoved] = useState<Removed | null>(null);

  const reset = (next: CardBook) => {
    setBook(next);
    setRemoved(null);
  };

  // Choosing a card makes it the default. If it was the backup, the
  // two swap roles: the old default becomes the backup, and the
  // Default and Backup pills cross on their way.
  const choose = (id: string) =>
    setBook((value) =>
      value.defaultId === id
        ? value
        : {
            ...value,
            backupId: value.backupId === id ? value.defaultId : value.backupId,
            defaultId: id,
          }
    );

  const remove = (id: string) => {
    const index = book.cards.findIndex((card) => card.id === id);
    const card = book.cards[index];
    if (!card || id === book.defaultId) {
      return;
    }
    setRemoved({
      card,
      index,
      key: Date.now(),
      wasBackup: book.backupId === id,
    });
    setBook((value) => ({
      ...value,
      backupId: value.backupId === id ? null : value.backupId,
      cards: value.cards.filter((each) => each.id !== id),
    }));
  };

  const undo = () => {
    if (!removed) {
      return;
    }
    setBook((value) => {
      const cards = [...value.cards];
      cards.splice(removed.index, 0, removed.card);
      return {
        ...value,
        backupId: removed.wasBackup ? removed.card.id : value.backupId,
        cards,
      };
    });
    setRemoved(null);
  };

  const add = (card: SavedCard) =>
    setBook((value) => ({ ...value, cards: [...value.cards, card] }));

  const update = (id: string, edit: CardEdit) =>
    setBook((value) => {
      let { backupId } = value;
      if (edit.backup) {
        backupId = id;
      } else if (backupId === id) {
        backupId = null;
      }
      return {
        ...value,
        backupId,
        cards: value.cards.map((card) =>
          card.id === id
            ? {
                ...card,
                expires: edit.expires,
                name: edit.name,
                nickname: edit.nickname || undefined,
                // A new date typed in by hand replaces the bank's.
                updatedByBank:
                  edit.expires === card.expires ? card.updatedByBank : false,
                // A new number is a new card: its brand and last four,
                // and the old card's decline no longer applies.
                ...(edit.number
                  ? {
                      brand: edit.number.brand,
                      declinedOn: undefined,
                      last4: edit.number.last4,
                    }
                  : {}),
              }
            : card
        ),
      };
    });

  // A declined card went through on retry: clear the decline, and take
  // whatever new details the bank sent (card account updater).
  const retried = (id: string, details: Partial<SavedCard> = {}) =>
    setBook((value) => ({
      ...value,
      cards: value.cards.map((card) =>
        card.id === id ? { ...card, ...details, declinedOn: undefined } : card
      ),
    }));

  return {
    add,
    book,
    choose,
    clearRemoved: () => setRemoved(null),
    remove,
    removed,
    reset,
    retried,
    undo,
    update,
  };
};

import { BRAND_NAME } from "./brand-marks";
import type { CardBrand } from "./brand-marks";

/* Saved cards, their health, and the checks behind Add card. */

export interface SavedCard {
  /** Your id for the card (e.g. the payment provider's). */
  id: string;
  /** "visa", "mastercard" or "amex": picks the logo. */
  brand: CardBrand;
  /** The last four digits. */
  last4: string;
  /** MM/YY */
  expires: string;
  /** Name on the card. */
  name: string;
  /** A label you give it, e.g. "Company card". */
  nickname?: string;
  /** Who added it, shown in the card editor. */
  addedBy: string;
  /** When it was added, as you want it shown. */
  addedOn: string;
  /** The last charge failed on this date. */
  declinedOn?: string;
  /** The bank sent new details (card account updater). */
  updatedByBank?: boolean;
}

/** The cards, which one is charged, and which one is tried if it fails. */
export interface CardBook {
  /** Up to four saved cards, in the order they show. */
  cards: SavedCard[];
  /** Id of the card that's charged. */
  defaultId: string;
  /** Id of the card tried when the default fails, or null. */
  backupId: string | null;
}

export type Health = "declined" | "expired" | "updated" | "expiring" | "ok";

// The demo's today: 20 November 2026.
const NOW = { month: 11, year: 2026 };

export const monthsAway = (expires: string) => {
  const [mm, yy] = expires.split("/").map(Number);
  return ((yy ?? 0) + 2000 - NOW.year) * 12 + ((mm ?? 0) - NOW.month);
};

export const healthOf = (card: SavedCard): Health => {
  if (card.declinedOn) {
    return "declined";
  }
  if (monthsAway(card.expires) < 0) {
    return "expired";
  }
  if (card.updatedByBank) {
    return "updated";
  }
  return monthsAway(card.expires) <= 2 ? "expiring" : "ok";
};

/** The words under the number, one per health. */
export const statusLine = (card: SavedCard) =>
  ({
    declined: `Declined on ${card.declinedOn}`,
    expired: `Expired ${card.expires}`,
    expiring: `Expires soon, ${card.expires}`,
    ok: `Expires ${card.expires}`,
    updated: `Updated by your bank, expires ${card.expires}`,
  })[healthOf(card)];

export const describe = (card: SavedCard) =>
  `${BRAND_NAME[card.brand]} ending ${card.last4}`;

/** A card can be charged unless it has expired. */
export const canCharge = (card: SavedCard) => healthOf(card) !== "expired";

/* ── Add card ─────────────────────────────────────────── */

/** The brand from the first digits, as soon as they say it. */
export const detectBrand = (digits: string): CardBrand | null => {
  if (/^3[47]/.test(digits)) {
    return "amex";
  }
  if (/^(5[1-5]|2(2[2-9]|[3-6]\d|7[01]|720))/.test(digits)) {
    return "mastercard";
  }
  if (digits.startsWith("4")) {
    return "visa";
  }
  return null;
};

export const numberLength = (brand: CardBrand | null) =>
  brand === "amex" ? 15 : 16;

/** 4242424242424242 → "4242 4242 4242 4242"; Amex groups 4-6-5. */
export const formatNumber = (digits: string, brand: CardBrand | null) => {
  const groups = brand === "amex" ? [4, 6, 5] : [4, 4, 4, 4];
  const parts: string[] = [];
  let at = 0;
  for (const size of groups) {
    if (at >= digits.length) {
      break;
    }
    parts.push(digits.slice(at, at + size));
    at += size;
  }
  return parts.join(" ");
};

/** The checksum every card number carries (Luhn). */
export const luhn = (digits: string) => {
  let sum = 0;
  for (let index = 0; index < digits.length; index += 1) {
    let digit = Number(digits[digits.length - 1 - index]);
    if (index % 2 === 1) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }
    sum += digit;
  }
  return digits.length > 0 && sum % 10 === 0;
};

export const maskExpiry = (raw: string) => {
  const digits = raw.replaceAll(/\D/g, "").slice(0, 4);
  return digits.length > 2
    ? `${digits.slice(0, 2)}/${digits.slice(2)}`
    : digits;
};

export const expiryError = (value: string) => {
  const match = /^(\d{2})\/(\d{2})$/.exec(value);
  const month = Number(match?.[1]);
  if (!match || month < 1 || month > 12) {
    return "Enter the date as MM/YY, like 04/29.";
  }
  if (monthsAway(value) < 0) {
    return "This date has passed. Use the date on your card.";
  }
  return null;
};

/* ─────────────────────────────────────────────────────────
 * BILLING MOTION: every duration and curve in this block, in one place. Built on the checkout
 * button's model: springs for anything that changes size or place
 * (they retarget mid-flight), a blur cross-fade for content swaps.
 *
 *   dialog   open 250ms / close 150ms, ease-out (CSS, in the dialog)
 *   morph    height follows content: react-use-measure (offsetSize)
 *            on the inner div, the outer animates to it; spring,
 *            visualDuration 0.23s, bounce 0 (tuned by eye: 0.18 read as
 *            a jump on ~390px tab switches, 0.3 as slow). Held at "auto" until the dialog has
 *            finished opening, and always "auto" under reduced motion.
 *   step     content swaps (method panels, card ↔ editor, summary ↔
 *            form) in popLayout: in = opacity + blur 6px → 0, 300ms
 *            ease-out-cubic; out = the reverse on a 0.25s spring.
 *            The blur hides the moment the two overlap.
 *   layout   slots reflow after add / remove / undo: spring 0.25 b0
 *   enter    small things arriving (new card, toast), 200ms out
 *   exit     small things leaving, 150ms out
 *   leave    a removed card: fade, scale 0.92, blur 4px, 180ms out
 *   swap     icon cross-fade (dot ↔ ✎🗑, brand logo while typing):
 *            scale 0.25 → 1, opacity, blur 4px → 0, spring 0.3 b0
 *   roll     a line of text that changes rolls up, 200ms out
 *   undo     the undo bar empties over 5s, linear (it's a clock)
 *   verify   "Verifying with your bank…" holds 1.2s, then ✓ 0.5s
 * ───────────────────────────────────────────────────────── */

export const EASE = {
  inOut: [0.645, 0.045, 0.355, 1] as const,
  out: [0.23, 1, 0.32, 1] as const,
  outCubic: [0.215, 0.61, 0.355, 1] as const,
  /** Speed falls in a straight line: rolls and counters, no tail. */
  outQuad: [0.5, 1, 0.89, 1] as const,
};

export const MOTION = {
  enter: { duration: 0.2, ease: EASE.out },
  exit: { duration: 0.15, ease: EASE.out },
  layout: { bounce: 0, duration: 0.25, type: "spring" as const },
  leave: { duration: 0.18, ease: EASE.out },
  morph: { bounce: 0, type: "spring" as const, visualDuration: 0.23 },
  roll: { duration: 0.2, ease: EASE.out },
  swap: { bounce: 0, duration: 0.3, type: "spring" as const },
};

/** Wait, for the beats between steps (e.g. ✓ before a slot turns). */
export const hold = async (ms: number) => {
  // oxlint-disable-next-line promise/avoid-new
  await new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
};

export const TIMING = {
  doneHold: 500,
  undoFor: 5000,
  verify: 1200,
};

export const SWAP_IN = {
  animate: { filter: "blur(0px)", opacity: 1, scale: 1 },
  exit: { filter: "blur(4px)", opacity: 0, scale: 0.25 },
  initial: { filter: "blur(4px)", opacity: 0, scale: 0.25 },
};

export const FADE_ONLY = {
  animate: { opacity: 1 },
  exit: { opacity: 0 },
  initial: { opacity: 0 },
};

/** Content swaps: blur cross-fade; opacity only under reduced motion
 *  (blur and scale are the vestibular triggers, the fade carries the
 *  meaning). Use inside AnimatePresence mode="popLayout". */
export const stepVariants = (reduce: boolean) =>
  reduce
    ? {
        animate: { opacity: 1, transition: { duration: 0.15 } },
        exit: { opacity: 0, transition: { duration: 0.1 } },
        initial: { opacity: 0 },
      }
    : {
        animate: {
          filter: "blur(0px)",
          opacity: 1,
          transition: { duration: 0.3, ease: EASE.outCubic },
        },
        exit: {
          filter: "blur(6px)",
          opacity: 0,
          transition: { bounce: 0, duration: 0.25, type: "spring" as const },
        },
        initial: { filter: "blur(6px)", opacity: 0 },
      };

/* ─────────────────────────────────────────────────────────
 * SURFACES: shadows for elevation, never a 1px ring or border.
 *
 *   lift    soft depth (light); in dark the surface colour lifts it
 *   button  outline buttons: a small contact shadow, no ring
 *
 * A transparent 1px border sits under each, so forced-colors mode (which
 * drops box-shadow) still draws an edge.
 * ───────────────────────────────────────────────────────── */

export const LIFT =
  "border border-transparent shadow-[0_1px_2px_0_oklch(0_0_0/0.05),0_2px_8px_-2px_oklch(0_0_0/0.08),0_8px_24px_-8px_oklch(0_0_0/0.08)] dark:shadow-none";

export const RING_BUTTON =
  "border border-transparent shadow-[0_1px_2px_0_oklch(0_0_0/0.1),0_1px_3px_0_oklch(0_0_0/0.06)] hover:shadow-[0_1px_2px_0_oklch(0_0_0/0.12),0_2px_6px_-1px_oklch(0_0_0/0.1)] dark:border-transparent dark:shadow-none dark:hover:shadow-none";
